ts_message("chunk #46 `conv_cor_wn_pop` start")
sites <- unique(gsub("_.*", "", colnames(hapfire)))

# windows as the resampling units for the block bootstrap below
conv_cor_blocks_kmate <- create_blocks(gen0, chrom, pos, 15000, block_by = "snp", sep = "_")

output_conv_cor_kmate <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/convergence_correlation_wn_env_kmate.tsv",
  sep = ""
)

output_conv_cor_blocks_kmate <- paste(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/convergence_correlation_by_block_wn_env_kmate.tsv",
  sep = ""
)

folder_path <- dirname(output_conv_cor_kmate)
if (!dir.exists(folder_path)) {
  dir.create(folder_path, recursive = TRUE, showWarnings = FALSE)
}

for (a in sites) {
  print(paste("Site:", a))
  hap_site <- hapfire %>%
    dplyr::select(starts_with(paste(a, "_", sep = ""))) %>%
    collect()

  if (ncol(hap_site) < 2) {
    print("Too few columns. Skipping to next site...")
    next
  }

  # sort columns into generation order, then prepend the shared seedmix as t=0
  hap_site <- hap_site %>%
    relocate(all_of(sort(colnames(hap_site))))

  gens <- as.integer(gsub("_", "", str_extract(colnames(hap_site), "_[0-9]_")))

  hap_site <- cbind(gen0$X0_0_0, hap_site)
  colnames(hap_site)[1] <- paste(a, "_0_0", sep = "")

  site_mat <- as.matrix(hap_site)
  rm(hap_site); gc()

  for (t in 1:max(gens)) {
    # interval t: change from gen t-1 to gen t, aligned by replicate
    cols_t <- which(gens == t)
    if (t == 1) {
      pdiffs <- site_mat[, cols_t, drop = FALSE] - site_mat[, 1]
    } else {
      reps_t <- gsub("^.*_", "", colnames(site_mat)[cols_t])
      cols_t1 <- match(paste(a, t - 1, reps_t, sep = "_"), colnames(site_mat))
      keep <- !is.na(cols_t1)
      pdiffs <- site_mat[, cols_t[keep], drop = FALSE] - site_mat[, cols_t1[keep], drop = FALSE]
    }

    # per-window components for the block bootstrap
    site_block_rows <- NULL
    for (w in unique(conv_cor_blocks_kmate$window)) {
      idx <- conv_cor_blocks_kmate$window == w
      if (sum(idx) <= 1) next
      w_cor <- conv_cor_wn_pop(pdiffs[idx, , drop = FALSE])
      block_row <- data.frame(
        window = w,
        site = a,
        gen = t,
        S = sum(idx),
        conv_cor_numer = w_cor[1],
        conv_cor_denom = w_cor[2]
      )
      append_table(block_row, output_conv_cor_blocks_kmate)
      site_block_rows <- rbind(site_block_rows, block_row)
    }

    # genome-wide row as the S-weighted ratio-of-sums across blocks
    conv_cor_row <- data.frame(
      site = a,
      gen = t,
      S = sum(site_block_rows$S),
      conv_cor_numer = sum(site_block_rows$S * site_block_rows$conv_cor_numer) / sum(site_block_rows$S),
      conv_cor_denom = sum(site_block_rows$S * site_block_rows$conv_cor_denom) / sum(site_block_rows$S)
    )

    append_table(conv_cor_row, output_conv_cor_kmate)
  }
  rm(site_mat, pdiffs); gc()
}
