ts_message("chunk #47 `block bootstrap intervals` start")
conv_cor_blocks <- fread(paste0(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/convergence_correlation_by_block_wn_env_kmate.tsv"
))

win_ids <- unique(conv_cor_blocks$window)
W <- length(win_ids)
B <- 1000
alpha <- 0.05

boot_samples <- NULL

for (b in 1:B) {
  # resample windows with replacement: one multinomial draw shared by all
  # site x gen combinations, weighted by each window's variant count
  draws <- sample(win_ids, W, replace = TRUE)
  wcounts <- as.data.table(table(factor(draws, levels = win_ids)))
  names(wcounts) <- c("window", "N")

  boot <- conv_cor_blocks[wcounts, on = .(window), nomatch = NULL][
    , .(numer = sum(N * S * conv_cor_numer), denom = sum(N * S * conv_cor_denom)),
    by = .(site, gen)][
    , .(site, gen, b = b, conv_cor_boot = numer / denom)]

  boot_samples <- rbind(boot_samples, boot)
}

fwrite(boot_samples, paste0(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/conv_cor_wn_env_kmate_boot_samples.tsv"
), sep = "\t")

boot_summary <- boot_samples %>%
  group_by(site, gen) %>%
  summarize(lci = quantile(conv_cor_boot, alpha / 2),
            uci = quantile(conv_cor_boot, 1 - alpha / 2),
            conv_cor_mean = mean(conv_cor_boot))

fwrite(boot_summary, paste0(
  "/global/scratch/users/milesroberts/moi_lab_projects/grenenet-phase2/results/",
  today,
  "/conv_cor_wn_env_kmate_boot_summary.tsv"
), sep = "\t")
